/**
 * @method
 * @name scwin.checkForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param frm
 * @returns
 * @hidden N
*/
scwin.checkForm = async function (frm) {
    /* sdd-asis-lifecycle:begin checkForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const writeYn = ($c.util.getComponent('dlt_comInfo').getTotalRow() > 0);
    let alarmYn = false;
    var ob = $c.util.getComponent(["slc_listAcntgBasCd", "slc_listAcntgBasCd_2", "slc_listAcntgBasCd_r1", "slc_listAcntgBasCd_2_r1", "slc_listAcntgBasCd_r2", "slc_listAcntgBasCd_2_r2", "slc_listAcntgBasCd_r3", "slc_listAcntgBasCd_2_r3"][0]);
    const ob2 = frm.acntclsYy[0];
    const ob3 = frm.listInvstgFiscyyTpCd[0];
    const ob4 = $c.util.getComponent(["slc_audtOpinTpCd", "slc_audtOpinTpCd_2", "slc_audtOpinTpCd_r1", "slc_audtOpinTpCd_2_r1", "slc_audtOpinTpCd_r2", "slc_audtOpinTpCd_2_r2", "slc_audtOpinTpCd_r3", "slc_audtOpinTpCd_2_r3"][0]);
    const xx = new Array();
    for (let i = 0; i < 4; i++) {
        const obj = $c.util.getComponent(["slc_listAcntgBasCd", "slc_listAcntgBasCd_2", "slc_listAcntgBasCd_r1", "slc_listAcntgBasCd_2_r1", "slc_listAcntgBasCd_r2", "slc_listAcntgBasCd_2_r2", "slc_listAcntgBasCd_r3", "slc_listAcntgBasCd_2_r3"][i]);
        const obj2 = $c.util.getComponent(["slc_acntclsYy", "slc_acntclsYy_r1", "slc_acntclsYy_r2", "slc_acntclsYy_r3"][i]);
        const obj3 = $c.util.getComponent(["slc_audtOpinTpCd", "slc_audtOpinTpCd_2", "slc_audtOpinTpCd_r1", "slc_audtOpinTpCd_2_r1", "slc_audtOpinTpCd_r2", "slc_audtOpinTpCd_2_r2", "slc_audtOpinTpCd_r3", "slc_audtOpinTpCd_2_r3"][i]);
        const obj4 = $c.util.getComponent('slc_listInvstgFiscyyTpCd')[i];
        const tempWriteYn = writeYn[i].value;
        xx[i] = obj.getValue();
        if (tempWriteYn === 'Y') {
            if ((obj.getValue() == null ? '' : String(obj.getValue())) === '') {
                await $c.win.alert('회계기준을 입력하세요');
                obj.focus();
                return false;
            }
            if ((obj3.getValue() == null ? '' : String(obj3.getValue())) === '') {
                await $c.win.alert('감사의견을 입력하세요');
                obj3.focus();
                return false;
            }
            if ((obj2.getValue() == null ? '' : String(obj2.getValue())) === '') {
                await $c.win.alert('결산년도을 입력하세요');
                obj2.focus();
                return false;
            }
            if ((obj4.getValue() == null ? '' : String(obj4.getValue())) === '') {
                await $c.win.alert("당기 결산기를 입력하세요.");
                obj4.focus();
                return false;
            }
        } else {
            alarmYn = true;
            obj.setValue("");
        }
    }
    if (alarmYn) {
        if (!await $c.win.confirm('해당없음이 선택되어 있습니다.\n해당기의 입력 항목은 삭제됩니다.\n진행하시겠습니까?')) {
            for (let x = 0; x < 4; x++) {
                var ob = $c.util.getComponent(["slc_listAcntgBasCd", "slc_listAcntgBasCd_2", "slc_listAcntgBasCd_r1", "slc_listAcntgBasCd_2_r1", "slc_listAcntgBasCd_r2", "slc_listAcntgBasCd_2_r2", "slc_listAcntgBasCd_r3", "slc_listAcntgBasCd_2_r3"][x]);
                ob.setValue(xx[x]);
            }
            return;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


